      ans: (I) => { const s = I.s, n = s.length, f = Array(n).fill(0); let force = 0; for (let i = 0; i < n; i++) { force = s[i] === "R" ? n : s[i] === "L" ? 0 : Math.max(force - 1, 0); f[i] += force; } force = 0; for (let i = n - 1; i >= 0; i--) { force = s[i] === "L" ? n : s[i] === "R" ? 0 : Math.max(force - 1, 0); f[i] -= force; } return H.count(f, (x) => x === 0); },
