      gen: (lv, R) => { const r = L3(lv, 4, 5, 6), c = L3(lv, 4, 6, 7), mines = R.sample(H.cells(r, c), L3(lv, 2, 4, 5)); const M = new Set(mines.map(([y, x]) => y * 100 + x)); const nums = U.range(r).map((y) => U.range(c).map((x) => (M.has(y * 100 + x) ? -1 : H.count(PB.MOVES["8"], ([dy, dx]) => M.has((y + dy) * 100 + x + dx))))); const z = H.cells(r, c).filter(([y, x]) => nums[y][x] === 0); return z.length ? { r, c, nums, click: R.pick(z) } : null; },
      text: (I) => `Mines are marked *. You click the square marked ◎ (a 0). Revealing a 0 also reveals all its neighbours, recursively. How many squares get revealed?<div class="mono strong">${I.nums.map((row, y) => row.map((v, x) => (y === I.click[0] && x === I.click[1] ? "◎" : v < 0 ? "*" : v)).join(" ")).join("<br>")}</div>`,
